  var all=ranked.map(function(x,i){return {x:x,rank:i+1}}).concat(prov.map(function(x){return {x:x,rank:0}})).filter(function(item){return qOK(item.x.r.name)});
  var pageSize=100,pages=Math.max(1,Math.ceil(all.length/pageSize));
