function raceDiscipline(c){return raceDisciplineValue(c)}
function raceDepartment(c){
  var raw=String(c.department||c.departement||c.dept||c.location||c.city||c.commune||'');
  var n=norm(raw);
  if(n.indexOf('sarthe')>=0||/\b72\b/.test(raw))return 'Sarthe';
  if(n.indexOf('mayenne')>=0||/\b53\b/.test(raw))return 'Mayenne';
  if(n.indexOf('maine et loire')>=0||n.indexOf('maine-et-loire')>=0||/\b49\b/.test(raw))return 'Maine-et-Loire';
  return 'Non renseigné';
}
function searchTermsMatch(haystack,query){
  var terms=norm(query).trim().split(/\s+/).filter(Boolean);
  var text=norm(haystack);
  return !terms.length||terms.every(function(term){
    if(text.indexOf(term)>=0)return true;
    if(term==="saint")return text.indexOf(" st ")>=0;
    if(term==="sainte")return text.indexOf(" ste ")>=0;
    if(term==="st")return text.indexOf(" saint ")>=0||text.indexOf(" sainte ")>=0;
    if(term==="ste")return text.indexOf(" sainte ")>=0;
    if(term==="72")return text.indexOf(" sarthe ")>=0;
    if(term==="53")return text.indexOf(" mayenne ")>=0;
    if(term==="49")return text.indexOf(" maine et loire ")>=0;
    return false;
  });
}
function collectRaceSearchFields(value,out,depth){
  if(value==null||depth>3)return;
  if(typeof value==="string"||typeof value==="number"){out.push(String(value));return;}
  if(Array.isArray(value)){value.slice(0,40).forEach(function(v){collectRaceSearchFields(v,out,depth+1);});return;}
  if(typeof value==="object"){Object.keys(value).forEach(function(key){if(["results","participants","raw","html","image","logo","url","results_url","registration_url","poster_url"].indexOf(key)>=0)return;collectRaceSearchFields(value[key],out,depth+1);});}
}
function raceResultSearchText(items,title,byId){
  var names=[],raceFields=[];
  items.forEach(function(c){
    collectRaceSearchFields(c,raceFields,0);
    (c.results||[]).forEach(function(x){var r=byId[x.id],details=runnerDetails[x.id]||{};if(r)names.push(r.name||"",r.club||"",r.city||"",details.city||"",details.club||"");else names.push(x.pendingName||"",x.pendingCity||"");});
  });
  return norm([title].concat(raceFields,names).filter(Boolean).join(" "));
}
function ensureRaceCitiesLoaded(){
  if(raceCitiesLoaded||raceCitiesLoading)return raceCitiesLoading;
  var ids=[],seen=Object.create(null);
  S.races.forEach(function(c){(c.results||[]).forEach(function(x){if(x&&x.id&&!x.pending&&!seen[x.id]){seen[x.id]=1;ids.push(x.id);}});});
  if(!ids.length){raceCitiesLoaded=true;return Promise.resolve();}
  raceCitiesLoading=loadCitiesFor(ids).then(function(cities){
    Object.keys(cities||{}).forEach(function(id){runnerDetails[id]=Object.assign(runnerDetails[id]||{runner_id:id},{city:cities[id]});});
    raceCitiesLoaded=true;raceListCache=null;
    if(S.view==="races")refreshRaceSearchResults();
  }).catch(function(){raceCitiesLoaded=false;}).then(function(){raceCitiesLoading=null;});
  return raceCitiesLoading;
}
function getRaceListIndex(){
  if(raceListCache&&raceListCacheRaces===S.races&&raceListCacheRunners===S.runners)return raceListCache;
  var byId=Object.create(null),groups=Object.create(null),names=[],normalizedNames=[],seenNames=Object.create(null);
  S.runners.forEach(function(r){byId[r.id]=r;});window.eloRunnerIndex=byId;
  for(var i=S.races.length-1;i>=0;i--){var c=S.races[i],key=norm(c.event||c.name)+'|'+String(c.date||'');(groups[key]=groups[key]||[]).push(c);var name=String(c.name||'');if(name&&!seenNames[name]){seenNames[name]=1;names.push(name);normalizedNames.push(norm(name).trim());}}
  var list=Object.keys(groups).map(function(k){return groups[k];});
  var indexed=list.map(function(items){var title=items[0].event||items[0].name;return {items:items,title:title,haystack:raceResultSearchText(items,title,byId)};});
  raceListCache={list:indexed,names:names,normalizedNames:normalizedNames};raceListCacheRaces=S.races;raceListCacheRunners=S.runners;
  return raceListCache;
}
