function spark(h){
  if(h.length<2)return"";
  var mn=Math.min.apply(null,h),mx=Math.max.apply(null,h),w=240,ht=50,rg=(mx-mn)||1;
  var pts=h.map(function(v,i){return(i*w/(h.length-1)).toFixed(1)+","+(ht-(v-mn)/rg*(ht-8)-4).toFixed(1)}).join(" ");
  return '<svg viewBox="0 0 '+w+' '+ht+'" width="100%" height="50" role="img" aria-label="Évolution de l’Elo"><polyline points="'+pts+'" fill="none" stroke="var(--accent)" stroke-width="2"/></svg>';
}
