function promotePendingProfiles(){
  if(!S.admin)return 0;
  var created=0,createdByKey={};
  S.races.forEach(function(course){
    (course.results||[]).forEach(function(item){
      if(!item.pending||!item.pendingName||isAnonymousRunnerName(item.pendingName))return;
      var matches=S.runners.filter(function(r){return !r.demo&&sameRunnerName(r.name,item.pendingName)});
      var sourceCity=normCity(item.pendingCity||'');
      if(matches.length===1){
        var knownCity=normCity(matches[0].city||'');
        if(!sourceCity||(knownCity&&sourceCity===knownCity)){item.id=matches[0].id;delete item.pending;delete item.pendingKey;delete item.pendingName;delete item.pendingCity;delete item.reason;return;}
        if(!sourceCity||!knownCity)return;
      }
      if(matches.length>1){
        var cityMatches=matches.filter(function(r){return sourceCity&&normCity(r.city||'')===sourceCity;});
        if(cityMatches.length===1){item.id=cityMatches[0].id;delete item.pending;delete item.pendingKey;delete item.pendingName;delete item.pendingCity;delete item.reason;}
        return;
      }
      var key=norm(item.pendingName)+'|'+sourceCity;
      var runner=createdByKey[key];
      if(!runner){
        runner={id:uid(),name:String(item.pendingName).replace(/\s+/g,' ').trim(),sex:'',cat:'',city:String(item.pendingCity||'').trim()};
        S.runners.push(runner);createdByKey[key]=runner;created++;
      }
      item.id=runner.id;delete item.pending;delete item.pendingKey;delete item.pendingName;delete item.pendingCity;delete item.reason;
    });
  });
  return created;
}
