function sendGhostVirtualRaceTitles(){
  var frame=document.getElementById("ghost-frame");if(!frame||!frame.contentWindow||!Array.isArray(S.races))return;
  function getDistance(c){var raw=String(c.dist||c.distance||"").trim().replace(",",".");var d=parseFloat(raw);if(!(d>0)){var n=norm(raw);if(n.indexOf("semi")>=0)d=21.0975;else if(n.indexOf("marathon")>=0)d=42.195;}return Number.isFinite(d)&&d>0?d:0;}
  var races=S.races.filter(function(c){return c&&c.id!=null&&Array.isArray(c.results)&&c.results.some(function(a){return a&&!a.pending;});}).map(function(c){return{id:String(c.id),name:String(c.name||c.nom||"Course"),date:String(c.date||""),distance:getDistance(c),participantCount:c.results.filter(function(a){return a&&!a.pending;}).length,type:String(c.type||c.discipline||c.category||"Course")};}).sort(function(a,b){return String(b.date).localeCompare(String(a.date));});
  try{frame.contentWindow.postMessage({type:"elo-ghost-virtual-races",races:races},"*");}catch(e){}
}
function sendGhostRaceTitles(){
  var frame=document.getElementById("ghost-frame");
  if(!frame||!frame.contentWindow||!Array.isArray(S.races)||!Array.isArray(S.runners))return;
  var st=eloCache.all||ALL||{};
  var races=S.races.filter(function(c){return !!linkedRunner&&Array.isArray(c.results)&&c.results.some(function(a){return !a.pending&&String(a.id)===String(linkedRunner);});}).map(function(c){
    var rawDist=String(c.dist||c.distance||"").trim(),dist=parseFloat(rawDist.replace(",","."));
    if(!(dist>0)){var nd=norm(rawDist);if(nd.indexOf("semi")>=0)dist=21.0975;else if(nd.indexOf("marathon")>=0)dist=42.195;}
    if(!(dist>0))return null;
    return {id:String(c.id),name:String(c.name||c.nom||"Course"),date:c.date||"",type:String(c.type||c.discipline||c.category||"Route"),distance:dist,participantCount:(Array.isArray(c.results)?c.results.length:0)};
  }).filter(Boolean).sort(function(a,b){return String(b.date||"").localeCompare(String(a.date||""));});
  var current=linkedRunner?st[String(linkedRunner)+"|X"]:null;
  try{frame.contentWindow.postMessage({type:"elo-ghost-real-races",races:races,currentRunnerId:linkedRunner||null,currentRunnerElo:current&&current.n?Math.round(Number(current.elo)):null,currentRunnerN:current?Number(current.n):null,currentRunnerK:current?(current.n<5?40:24):null},"*");}catch(e){}
}
(function(){
  var frame=document.getElementById("ghost-frame");if(!frame)return;
  function sendError(message){try{frame.contentWindow.postMessage({type:"elo-ghost-race-data",error:message},"*");}catch(e){}}
  window.addEventListener("message",function(event){
    if(!frame.contentWindow||event.source!==frame.contentWindow||!event.data||event.data.type!=="elo-ghost-request-race")return;
    var course=S.races.find(function(c){return String(c.id)===String(event.data.raceId);});
    if(!course){sendError("Cette course n’a pas été retrouvée dans les données réelles. Choisis-la à nouveau.");return;}
    if(!linkedRunner){sendError("Connecte-toi à ton compte coureur pour retrouver ta position dans cette course.");return;}
    var st=eloCache.all||ALL||{},ownElo=st[String(linkedRunner)+"|X"];
    if(!ownElo||!Number(ownElo.n)||!Number.isFinite(Number(ownElo.elo))){sendError("Ton ELO officiel n’est pas encore disponible. Attends la fin du calcul du classement puis réessaie.");return;}
    function toSeconds(v){if(typeof v==="number"&&isFinite(v))return v;var raw=String(v||"").trim();if(/^\d+(?:\.\d+)?$/.test(raw))return Number(raw);if(raw.indexOf(":")>=0){var parts=raw.split(":").map(Number);if(parts.every(Number.isFinite)){var total=0;parts.forEach(function(x){total=total*60+x;});return total;}}return 0;}
    function getRank(a){var n=Number(a&&(a.rk||a.rank||a.position));return Number.isFinite(n)&&n>0?n:null;}
    var ordered=(Array.isArray(course.results)?course.results:[]).filter(function(a){return a&&!a.pending&&a.id&&toSeconds(a.time)>0;});
    ordered.sort(function(a,b){var ra=getRank(a),rb=getRank(b);if(ra!==null&&rb!==null&&ra!==rb)return ra-rb;if(ra!==null&&rb===null)return -1;if(ra===null&&rb!==null)return 1;return toSeconds(a.time)-toSeconds(b.time);});
    var ownIndex=ordered.findIndex(function(a){return String(a.id)===String(linkedRunner);});
    if(ownIndex<0){sendError("Tu ne figures pas dans les résultats de cette course. Choisis une course à laquelle tu as participé.");return;}
    var ownResult=ordered[ownIndex],ownTime=toSeconds(ownResult.time);
    var selected=ordered.slice(Math.max(0,ownIndex-10),Math.min(ordered.length,ownIndex+11)).filter(function(a){return String(a.id)!==String(linkedRunner);});
    var runners=[];
    selected.forEach(function(a){var p=st[String(a.id)+"|X"];if(!p||!Number(p.n)||!Number.isFinite(Number(p.elo)))return;var r=S.runners.find(function(x){return String(x.id)===String(a.id);})||{};runners.push({name:r.name||r.nom||a.name||a.nom||"Coureur",club:r.club||a.club||"",elo:Math.round(Number(p.elo)),experience:Number(p.n)||0,time:toSeconds(a.time),rank:getRank(a)});});
    if(runners.length<1){sendError("Il n’y a pas assez de coureurs avec un ELO calculé autour de ta position pour lancer cette simulation.");return;}
    function fmt(t){var h=Math.floor(t/3600),m=Math.floor((t%3600)/60),s=Math.floor(t%60);return h?String(h).padStart(2,"0")+":"+String(m).padStart(2,"0")+":"+String(s).padStart(2,"0"):String(m).padStart(2,"0")+":"+String(s).padStart(2,"0");}
    var rawDist=String(course.dist||course.distance||"").trim(),dist=parseFloat(rawDist.replace(",","."));
    if(!(dist>0)){var nd=norm(rawDist);if(nd.indexOf("semi")>=0)dist=21.0975;else if(nd.indexOf("marathon")>=0)dist=42.195;}
    if(!(dist>0)){sendError("La distance de cette course n’est pas renseignée.");return;}
    try{frame.contentWindow.postMessage({type:"elo-ghost-race-data",race:{id:String(course.id),name:String(course.name||course.nom||"Course"),date:course.date||"",type:String(course.type||course.discipline||course.category||"Route"),distance:dist,participantCount:ordered.length,nearbyCount:runners.length,currentRunnerRank:getRank(ownResult)||ownIndex+1,defaultTime:fmt(ownTime),runners:runners}},"*");}catch(e){}
  });
})();

(function(){
var frame=document.getElementById("ghost-frame");if(!frame)return;
var virtualRaceCacheId=null,virtualRaceCache=[];
function seconds(v){if(typeof v==="number"&&isFinite(v))return v;var raw=String(v==null?"":v).trim();if(/^\d+(?:\.\d+)?$/.test(raw))return Number(raw);if(raw.indexOf(":")>=0){var p=raw.split(":").map(Number);if(p.every(Number.isFinite)){var n=0;p.forEach(function(x){n=n*60+x;});return n;}}return 0;}
function format(t){t=Math.max(0,Math.round(t));var h=Math.floor(t/3600),m=Math.floor(t%3600/60),s=t%60;return(h?String(h).padStart(2,"0")+":":"")+String(m).padStart(2,"0")+":"+String(s).padStart(2,"0");}
function normalize(v){return String(v||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();}
function distance(c){var raw=String(c.dist||c.distance||"").trim().replace(",",".");var d=parseFloat(raw);if(!(d>0)){var n=normalize(raw);if(n.indexOf("semi")>=0)d=21.0975;else if(n.indexOf("marathon")>=0)d=42.195;}return Number.isFinite(d)&&d>0?d:0;}
function validName(name){var n=normalize(name);return !!n&&!/(^| )(xxx+|anonyme|anonymous|inconnu|inconnue|masked)( |$)/.test(n);}
window.addEventListener("message",function(event){
if(event.source!==frame.contentWindow||!event.data)return;var d=event.data;
if(d.type==="elo-ghost-request-virtual-races"){sendGhostVirtualRaceTitles();return;}
if(d.type==="elo-ghost-request-elo"){if(eloCache.all){sendGhostRaceTitles();}else{var ready=compute(undefined,"all");if(ready&&Object.keys(ready).length){ALL=ready;sendGhostRaceTitles();}}return;}
if(d.type!=="elo-ghost-request-virtual-race")return;
var course=(S.races||[]).find(function(c){return String(c.id)===String(d.raceId);});
if(!course){frame.contentWindow.postMessage({type:"elo-ghost-virtual-race-data",raceId:String(d.raceId),requestId:d.requestId,error:"Cette course n'a pas été retrouvée dans les données ELO COURSE."},"*");return;}
if(virtualRaceCacheId!==String(course.id)){
var runnerById=new Map((S.runners||[]).map(function(r){return[String(r.id),r];})),all=[];
(course.results||[]).forEach(function(a){if(!a||a.pending||a.id==null)return;var runner=runnerById.get(String(a.id));if(!runner)return;var name=String(runner.name||runner.nom||a.name||a.nom||"").trim();if(!validName(name))return;var time=seconds(a.time);if(!(time>0))return;var rankRaw=a.rk!=null?a.rk:(a.rank!=null?a.rank:a.position),rank=Number(rankRaw);all.push({id:String(runner.id),name:name,club:String(runner.club||a.club||""),category:String(runner.cat||runner.category||""),rank:Number.isFinite(rank)&&rank>0?rank:null,time:time,timeText:format(time)});});
all.sort(function(a,b){if(a.rank!==null&&b.rank!==null&&a.rank!==b.rank)return a.rank-b.rank;if(a.rank!==null&&b.rank===null)return -1;if(a.rank===null&&b.rank!==null)return 1;return a.time-b.time;});
virtualRaceCacheId=String(course.id);virtualRaceCache=all;
}
var all=virtualRaceCache,q=normalize(d.query),matches=q?all.filter(function(r){return normalize(r.name+" "+r.club).indexOf(q)>=0;}):all,limit=q?40:60;
frame.contentWindow.postMessage({type:"elo-ghost-virtual-race-data",raceId:String(course.id),requestId:d.requestId,totalParticipants:all.length,matchingCount:matches.length,participants:matches.slice(0,limit),distance:distance(course)},"*");
});
})();

